**Key idea:** Put **legality** (what the protocol allows) as hard constraints in the transaction; put **traffic shape** (weights, scenarios) in the sequence/test via inline `dist` and knobs. Then **measure** the actual distribution with coverage and a histogram, because hard constraints (e.g. 4 KB boundary, payload size) can skew what `dist` asked for.

```mermaid
flowchart LR
  TXN["txn class: legality constraints<br/>(size, len, wrap, 4KB, payload)"] --> SEQ["sequence: dist knobs<br/>per scenario"]
  SEQ --> DRV["driver"]
  DRV --> MON["monitor"]
  MON --> STAT["stats subscriber:<br/>covergroup + histogram"]
```

### Code
```systemverilog
typedef enum bit [1:0] {FIXED = 0, INCR = 1, WRAP = 2} burst_e;

class bus_txn extends uvm_sequence_item;
  rand bit [31:0] addr;
  rand bit [7:0]  len;                 // beats - 1
  rand bit [2:0]  size;                // bytes per beat = 1 << size
  rand burst_e    burst;
  rand bit [7:0]  data[];
  `uvm_object_utils(bus_txn)
  function new(string name = "bus_txn"); super.new(name); endfunction

  // ---------- legality: never disabled by tests ----------
  constraint c_size    { size <= 3'd3; }                              // 64-bit bus
  constraint c_fixed   { burst == FIXED -> len < 16; }
  constraint c_wrap    { burst == WRAP  -> len inside {1, 3, 7, 15};
                         burst == WRAP  -> (addr & ((32'd1 << size) - 1)) == 0; }
  constraint c_4k      { burst == INCR  ->
                           ((addr[11:0] & ~((12'd1 << size) - 1)) + ((32'(len) + 1) << size)) <= 4096; }
  constraint c_payload { data.size() == ((32'(len) + 1) << size); }
endclass

class mixed_burst_seq extends uvm_sequence #(bus_txn);
  `uvm_object_utils(mixed_burst_seq)
  int unsigned n_txn = 500;
  function new(string name = "mixed_burst_seq"); super.new(name); endfunction
  task body();
    repeat (n_txn) begin
      req = bus_txn::type_id::create("req");
      start_item(req);
      if (!req.randomize() with {
            burst dist {INCR := 70, WRAP := 20, FIXED := 10};
            len   dist {0 := 20, [1:3] :/ 30, [4:15] :/ 30, [16:255] :/ 20};
          })
        `uvm_fatal("RAND", "bus_txn randomize failed")
      finish_item(req);
    end
  endtask
endclass

class burst_stats extends uvm_subscriber #(bus_txn);
  `uvm_component_utils(burst_stats)
  int unsigned n_by_burst[burst_e];
  int unsigned n_by_len[int];

  covergroup cg with function sample(bus_txn t);
    cp_burst: coverpoint t.burst { bins b[] = {FIXED, INCR, WRAP}; }
    cp_len:   coverpoint t.len   { bins single = {0}; bins short_b = {[1:3]};
                                   bins med = {[4:15]}; bins long_b = {[16:255]}; }
    cp_size:  coverpoint t.size  { bins s[] = {[0:3]}; }
    cp_end4k: coverpoint ((t.addr[11:0] + ((32'(t.len) + 1) << t.size)) == 4096) { bins at_boundary = {1}; }
    x_burst_len: cross cp_burst, cp_len {
      ignore_bins wrap_single = binsof(cp_burst) intersect {WRAP}  && binsof(cp_len.single);
      ignore_bins wrap_long   = binsof(cp_burst) intersect {WRAP}  && binsof(cp_len.long_b);
      ignore_bins fixed_long  = binsof(cp_burst) intersect {FIXED} && binsof(cp_len.long_b);
    }
  endgroup

  function new(string name, uvm_component parent);
    super.new(name, parent);
    cg = new();
  endfunction

  function void write(bus_txn t);
    n_by_burst[t.burst]++;
    n_by_len[t.len]++;
    cg.sample(t);
  endfunction

  function void report_phase(uvm_phase phase);
    foreach (n_by_burst[b])
      `uvm_info("STATS", $sformatf("%s: %0d", b.name(), n_by_burst[b]), UVM_LOW)
    `uvm_info("STATS", $sformatf("coverage = %0.1f%%", cg.get_coverage()), UVM_LOW)
  endfunction
endclass
```

